  "CommandPalette": {
    "react": "import { useState } from 'react';\nimport { Button, CommandPalette } from '@larose-ui/react';\n\nexport default function App() {\n  const [open, setOpen] = useState(true);\n  return (\n    <>\n      <Button onClick={() => setOpen(true)}>Open commands</Button>\n      <CommandPalette\n        open={open}\n        onOpenChange={setOpen}\n        items={[\n          { id: 'new', label: 'New file', group: 'File', onSelect: () => setOpen(false) },\n          { id: 'save', label: 'Save', group: 'File', onSelect: () => setOpen(false) },\n        ]}\n      />\n    </>\n  );\n}\n",
    "vue": "<script setup lang=\"ts\">\nimport { ref } from 'vue';\nimport { Button, CommandPalette } from '@larose-ui/vue';\nconst open = ref(true);\nconst items = [\n  { id: 'new', label: 'New file', group: 'File', onSelect: () => (open.value = false) },\n  { id: 'save', label: 'Save', group: 'File', onSelect: () => (open.value = false) },\n];\n</script>\n\n<template>\n  <Button @click=\"open = true\">Open commands</Button>\n  <CommandPalette :open=\"open\" :items=\"items\" @open-change=\"open = $event\" />\n</template>\n",
    "svelte": "<script lang=\"ts\">\n  import { Button, CommandPalette } from '@larose-ui/svelte';\n  let open = $state(true);\n  const items = [\n    { id: 'new', label: 'New file', group: 'File', onSelect: () => (open = false) },\n    { id: 'save', label: 'Save', group: 'File', onSelect: () => (open = false) },\n  ];\n</script>\n\n<Button onclick={() => (open = true)}>Open commands</Button>\n<CommandPalette {open} {items} onOpenChange={(v) => (open = v)} />\n"
  },
